function clamp(value: number, minimum = 0, maximum = 1) { return Math.max(minimum, Math.min(maximum, value)); }
function clock(seconds: number) { const safe = Math.max(0, seconds); const minutes = Math.floor(safe / 60); const remainder = safe - minutes * 60; return `${minutes}:${remainder.toFixed(remainder < 10 ? 1 : 0).padStart(remainder < 10 ? 4 : 2, "0")}`; }

function prepare(canvas: HTMLCanvasElement, width: number, height: number) {
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  const pixelWidth = Math.round(width * dpr); const pixelHeight = Math.round(height * dpr);
  if (canvas.width !== pixelWidth || canvas.height !== pixelHeight) { canvas.width = pixelWidth; canvas.height = pixelHeight; canvas.style.width = `${width}px`; canvas.style.height = `${height}px`; }
  const context = canvas.getContext("2d", { alpha: false }); if (!context) return null;
  context.setTransform(dpr, 0, 0, dpr, 0, 0); return context;
}

function sample(values: number[], progress: number) {
  if (!values.length || progress < 0 || progress > 1) return 0;
  const position = progress * (values.length - 1); const left = Math.floor(position); const fraction = position - left;
  return values[left] * (1 - fraction) + values[Math.min(values.length - 1, left + 1)] * fraction;
}

function envelope(peaks: number[], width: number) {
  const values = new Float32Array(width); const ratio = peaks.length / width;
  for (let x = 0; x < width; x++) {
    if (ratio >= 1) { const start = Math.floor(x * ratio); const end = Math.max(start + 1, Math.floor((x + 1) * ratio)); let peak = 0; for (let index = start; index < Math.min(end, peaks.length); index++) peak = Math.max(peak, peaks[index]); values[x] = peak; }
    else values[x] = sample(peaks, x / Math.max(1, width - 1));
  }
  return values;
}

function drawOverview(context: CanvasRenderingContext2D, bands: Bands, width: number, height: number) {
  const full = envelope(bands.full, width); const low = envelope(bands.low, width); const mid = envelope(bands.mid, width); const high = envelope(bands.high, width); const center = height / 2;
  context.fillStyle = "#050809"; context.fillRect(0, 0, width, height);
  for (let x = 0; x < width; x++) {
    const body = Math.max(1, full[x] * height * .44); const bass = Math.min(body, low[x] * height * .36); const mids = Math.min(body, mid[x] * height * .28); const highs = Math.min(body, high[x] * height * .2);
    context.fillStyle = "rgba(92,106,109,.42)"; context.fillRect(x, center - body, 1, body * 2);
    context.fillStyle = "rgba(255,82,66,.72)"; context.fillRect(x, center - bass, 1, bass * 2);
    context.fillStyle = "rgba(215,78,209,.68)"; context.fillRect(x, center - mids, 1, mids * 2);
    context.fillStyle = "rgba(67,237,213,.76)"; context.fillRect(x, center - highs, 1, highs * 2);
  }
}

