function rulerStep(visibleSeconds: number, width: number) {
  const target = visibleSeconds / Math.max(1, width / 92); const steps = [.1, .25, .5, 1, 2, 5, 10, 15, 30, 60, 120];
  return steps.find((step) => step >= target) || 300;
}

